module TreeRoom {
  // A tree room's trap-door lever, or the round room's at the top (house 0):
  // the trap door shuts if open, opens if shut.
  public func on_event(g, e) {
    switch (e) {
      case (#PullHatch(n)) { #SetHatch(n, not g.hatch, #Done) };
      case _ { #Done }
    }
  }
}

